<?php namespace App\Providers; use Illuminate\Support\ServiceProvider; use Resend\Client; use Resend\Transporters\HttpTransporter; use Resend\ValueObjects\Transporter\BaseUri; use Resend\ValueObjects\Transporter\Headers; use Resend\ValueObjects\ApiKey; class ResendVerifyProvider extends ServiceProvider { public function register(): void { $this->app->extend("resend", function ($client, $app) { return new Client(new HttpTransporter(new \GuzzleHttp\Client(["verify" => false]), BaseUri::from("api.resend.com"), Headers::withAuthorization(ApiKey::from(config("resend.api_key") ?? config("services.resend.key"))))); }); } }
